'use client'
import React from 'react'
import { useEffect } from 'react'
i

const Auth_success = () => {
    useEffect(() => {
        // search parameter from url
        const email = new URLSearchParams(window.location.search).get('email');
        if (!email) return;
        const response = axios.post('http://localhost:4444/getUserByEmail', { email });
        response.then((res) => {
            if (res.data.success) {
                localStorage.setItem('user', JSON.stringify(res.data.user));
                window.location.href = '/dashboard';
            } else {
                window.location.href = '/login';
            }
        }).catch((err) => {
            console.log(err);
            window.location.href = '/login';
        });
    }, []);

  return (
    <div className=' text-black text-3xl font-bold underline bg-amber-300'>Auth_success</div>
  )
}

export default Auth_success